INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('95024930de536445', 'brand_vetripaws', '320f10c21591266a', 1, 1, 1, 'live', 'The pill in the cheese, again', 'Every dog owner has lost the pill-in-cheese game, so the hook is instant and the strip is the obvious way out.', 'Any owner whose dog has ever found the pill', 'Bone & Joint', 'Pill fail then the swap', '["Your dog found the pill in the cheese again, didn''t they?", "Pill pocket, peanut butter, cheese. He beat all of them.", "I found his vitamin on the kitchen floor three hours later. That''s when I quit pills."]', '[{"label": "Open · 0 to 3s", "text": "Dog spits out or sniffs around the cheese and leaves the pill. Text: your dog found the pill again, didn''t they?"}, {"label": "Middle", "text": "Open the tin, pull one strip, lay it on the dog''s tongue. Hold the shot while it melts, about 30 seconds sped up is fine."}, {"label": "Close", "text": "Dog licking lips and looking for more. Say: no hiding, no standoff, no pill on the floor."}]', 'Dog sitting in front of you with a pill hidden in cheese, text on screen: your dog found the pill again, didn''t they?', 'Close up of the strip going on the tongue and simply disappearing, no chewing, no standoff', '[{"brand": "Wuffes", "what": "Film your dog spitting the pill back out of the cheese (or show the one you found on the floor). Then lay a VetriPaws strip on their tongue and let the camera roll while it melts away.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('e9f2bc4ca79c97ac', 'brand_vetripaws', '95024930de536445', 'upload', 'amb/brand_vetripaws/inspo-wuf-pill-cheese.mp4', 'Wuffes (inspiration)', 'Film your dog spitting the pill back out of the cheese (or show the one you found on the floor). Then lay a VetriPaws strip on their tongue and let the camera roll while it melts away.', '320f10c21591266a', 1, 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('6f9b3344ec0695b3', 'brand_vetripaws', '320f10c21591266a', 1, 2, 2, 'live', 'My old dog tells the story', 'Dog-voice captions make people stop, and owners of older dogs see their own dog in every clip.', 'Owner of a senior or big-breed dog', 'Bone & Joint', 'Dog POV captions', '["Mom, I''m getting older and I need to tell you something.", "I''m 11. Getting off the couch takes me a minute now.", "Every time I pant after a walk, it''s a little signal."]', '[{"label": "Open · 0 to 3s", "text": "Tight shot of your dog''s face, caption in the dog''s voice about getting older."}, {"label": "Middle", "text": "Clips of the slow parts: getting up after a nap, stairs, sniffing slowly in the yard. Then the strip going on the tongue at breakfast."}, {"label": "Close", "text": "Dog walking on the leash in good light. Caption: thanks for giving me what my joints need. More walks together."}]', 'Close up of the old dog''s face with caption: Mom, I wish you could tell what my joints feel like', 'The strip moment told by the dog: she gives me this thing that melts on my tongue', '[{"brand": "Dog is Human", "what": "Film your older dog through a normal day (slow off the bed, the stairs, the walk) and write the captions in your dog''s voice. Show the strip as part of the morning and end on the walk.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('5d856711b54dd285', 'brand_vetripaws', '6f9b3344ec0695b3', 'upload', 'amb/brand_vetripaws/inspo-dih-senior-pov.mp4', 'Dog is Human (inspiration)', 'Film your older dog through a normal day (slow off the bed, the stairs, the walk) and write the captions in your dog''s voice. Show the strip as part of the morning and end on the walk.', '320f10c21591266a', 1, 1, 2);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('cc8eb5b29d143d72', 'brand_vetripaws', '2efba8ff5a73e351', 1, 3, 3, 'live', 'It wasn''t my husband''s breath', 'A tiny skit with a twist ending gets watched to the end and shares well, and every dog owner knows morning dog breath.', 'A couple (or roommates) with a dog that sleeps in the bed', 'Fresh Breath', 'Two-person bed skit', '["For the longest time I thought my husband had terrible morning breath.", "Turns out it wasn''t him. It was the dog.", "Morning breath in our bed has a name, and it''s Biscuit."]', '[{"label": "Open · 0 to 3s", "text": "Both in bed, one turns away from the other with a face. Text: bad morning breath?"}, {"label": "Middle", "text": "Dog lifts its head from the blanket. Cut to the kitchen: strip on the tongue, melts while you make coffee."}, {"label": "Close", "text": "Back in bed, dog gives a kiss and nobody flinches. Say: one strip in the morning, that''s it."}]', 'Partner waking up and recoiling. Text: bad morning breath?', 'The reveal: the dog pops its head up between you', '[{"brand": "Zesty Paws", "what": "Two people in bed, one rolls over and makes a face at the partner. Reveal the dog between you is the real culprit, then show the strip as part of your morning.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8295b1c95b195e91', 'brand_vetripaws', 'cc8eb5b29d143d72', 'upload', 'amb/brand_vetripaws/inspo-zp-morning-breath.mp4', 'Zesty Paws (inspiration)', 'Two people in bed, one rolls over and makes a face at the partner. Reveal the dog between you is the real culprit, then show the strip as part of your morning.', '2efba8ff5a73e351', 1, 1, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('6dc6d598d6c93bfc', 'brand_vetripaws', '502a835331b56cfd', 1, 4, 4, 'live', 'A jar full of my dog''s fur', 'A jar of fur is a visual nobody scrolls past, and it says shedding without a single word.', 'Owner of a heavy shedder (lab, husky, shepherd, golden)', 'Skin & Coat', 'Talking head with a prop', '["If you vacuum dog hair every single day, watch this.", "This is one day of fur. One day.", "Yes, dogs shed. But all year long?"]', '[{"label": "Open · 0 to 3s", "text": "Jar of fur held right up to the lens."}, {"label": "Middle", "text": "Fur on the couch, on your clothes, on the bed. Back to you talking: the coat starts with the skin. Strip on the tongue, gone in about 30 seconds."}, {"label": "Close", "text": "Hand running down your dog''s coat. Say you''re giving their skin and coat some daily support, and that it comes with a 30 day money back guarantee."}]', 'A clear jar packed with dog hair held up to the camera', 'Hand swipe across the couch or black pants, covered in fur', '[{"brand": "Petsmont", "what": "Hold up a jar (or bag) of fur you collected from one day of vacuuming and talk to camera about the shedding. Show the couch, your clothes, then the strip as your daily step.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('5e46f1fda5dd8886', 'brand_vetripaws', '6dc6d598d6c93bfc', 'upload', 'amb/brand_vetripaws/inspo-pts-fur-vacuum.mp4', 'Petsmont (inspiration)', 'Hold up a jar (or bag) of fur you collected from one day of vacuuming and talk to camera about the shedding. Show the couch, your clothes, then the strip as your daily step.', '502a835331b56cfd', 1, 1, 4);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('968797312a0d47f5', 'brand_vetripaws', '502a835331b56cfd', 0, 0, 5, 'live', 'I tried everything', 'Owners of picky dogs feel seen by the montage of failed tricks, and the strip ends the search.', 'Owner of a picky or suspicious dog', 'Skin & Coat', 'Frustrated owner montage', '["I''ve tried everything to get my dog to take his vitamins.", "Cheese, peanut butter, pill pockets, crushing it into dinner. Nothing.", "My dog can find a pill in a meatball from across the room."]', '[{"label": "Open · 0 to 3s", "text": "Dog sniffing the bowl and walking off. You shrug at camera."}, {"label": "Middle", "text": "Quick cuts of each trick failing. Then the tin, one strip, on the tongue."}, {"label": "Close", "text": "Dog licks lips and stares at the tin. Say: finally, something he actually takes."}]', 'Dog walking away from a bowl you clearly worked hard on', 'The pile of failed tricks on the counter', '[{"brand": "Pupford", "what": "Show every trick you''ve used to get a vitamin into your dog: pill pockets, cheese, peanut butter, crushing it into food. Then the strip, which just goes on the tongue.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('4f0b47da234b6aaf', 'brand_vetripaws', '968797312a0d47f5', 'upload', 'amb/brand_vetripaws/inspo-pup-tried-everything.mp4', 'Pupford (inspiration)', 'Show every trick you''ve used to get a vitamin into your dog: pill pockets, cheese, peanut butter, crushing it into food. Then the strip, which just goes on the tongue.', '502a835331b56cfd', 1, 1, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('e6825155ce64b9b2', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 6, 'live', 'Picky eater? Never heard of her', 'A quick meme format with one clean payoff, easy to film in one take.', 'Anyone with a dog that is fussy about pills', 'Fresh Breath', 'Meme caption, one beat', '["Picky eater? Never heard of her.", "She refuses every pill. Watch this.", "The pickiest dog I know, versus one strip."]', '[{"label": "Open · 0 to 3s", "text": "Your dog side-eyeing a pill or a bowl. Text: picky eater?"}, {"label": "Middle", "text": "Strip out of the tin, dog takes it on the tongue. Text: never heard of her."}, {"label": "Close", "text": "Dog sitting waiting for another one."}]', 'Text on screen: picky eater?', 'The dog leaning in for the strip', '[{"brand": "Pupford", "what": "Short and funny: text says picky eater, then your dog happily takes the strip off your fingers like it''s a treat. Under 15 seconds.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('cc7369fce031b084', 'brand_vetripaws', 'e6825155ce64b9b2', 'upload', 'amb/brand_vetripaws/inspo-pup-never-heard.mp4', 'Pupford (inspiration)', 'Short and funny: text says picky eater, then your dog happily takes the strip off your fingers like it''s a treat. Under 15 seconds.', '2efba8ff5a73e351', 1, 1, 6);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('9dde9206c3c966e2', 'brand_vetripaws', '320f10c21591266a', 0, 0, 7, 'live', 'Her favorite part of the day', 'Seeing a dog get excited for a supplement answers the only question that matters: will mine take it?', 'Owner with a food-motivated dog, or two dogs', 'Bone & Joint', 'Daily routine voiceover', '["This is my dog''s favorite part of the day.", "Ironically, it''s also the healthiest part of his day.", "Watch what happens when I open this tin."]', '[{"label": "Open · 0 to 3s", "text": "Tin opens, dog runs in."}, {"label": "Middle", "text": "Strip on the tongue, close up while it melts. Say how much easier this is than a pill."}, {"label": "Close", "text": "Both dogs (or one) sitting pretty for theirs."}]', 'Dog sprinting into the kitchen at the sound of the tin', 'Strip on the tongue, gone, dog asking for more', '[{"brand": "Ruff Greens", "what": "Film your dog running to you when the VetriPaws tin comes out. Talk over it: this is the healthiest part of their day and they think it''s a treat.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('57cd2a6213c2e4d6', 'brand_vetripaws', '9dde9206c3c966e2', 'upload', 'amb/brand_vetripaws/inspo-rg-favorite-part.mp4', 'Ruff Greens (inspiration)', 'Film your dog running to you when the VetriPaws tin comes out. Talk over it: this is the healthiest part of their day and they think it''s a treat.', '320f10c21591266a', 1, 1, 7);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('897f8910e532a202', 'brand_vetripaws', '502a835331b56cfd', 0, 0, 8, 'live', 'The pile versus one strip', 'The cluttered table makes the point that most of that stuff never got eaten, and one strip is simple.', 'Owner who has a cupboard full of half-used supplements', 'Skin & Coat', 'Table demo, talking to camera', '["This is everything I''ve bought my dog that he refused to eat.", "Half of these are still full.", "A supplement only works if your dog actually takes it."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot of the cluttered table, you behind it."}, {"label": "Middle", "text": "Pick up a couple and say what went wrong (spat out, wouldn''t touch the bowl). Push it all aside. One strip."}, {"label": "Close", "text": "Dog takes the strip. Say the controlling line: it only works if they take it."}]', 'A table covered in half-used tubs and pill bottles', 'Sweeping the pile aside', '[{"brand": "PetLab Co.", "what": "Line up every pill, powder and chew you''ve bought for your dog on the table. Push it all aside, hold up one VetriPaws strip, and give it to your dog.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ec577dbbeb656699', 'brand_vetripaws', '897f8910e532a202', 'upload', 'amb/brand_vetripaws/inspo-plc-supplement-pile.mp4', 'PetLab Co. (inspiration)', 'Line up every pill, powder and chew you''ve bought for your dog on the table. Push it all aside, hold up one VetriPaws strip, and give it to your dog.', '502a835331b56cfd', 1, 1, 8);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('9265756226e91e3c', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 9, 'live', 'Replying to: does your dog actually take it?', 'A comment reply feels like an honest answer to a real question, which is exactly the doubt people have about supplements.', 'Creator with a dog that sits in their lap', 'Fresh Breath', 'Comment reply', '["Everyone keeps asking if my dog actually takes these.", "Replying to Sarah: yes, and I''ll show you.", "You asked how I get vitamins into him. Here''s the whole thing."]', '[{"label": "Open · 0 to 3s", "text": "Comment on screen, you holding your dog."}, {"label": "Middle", "text": "Open the tin, one strip, on the tongue. Keep the camera on it till it''s gone."}, {"label": "Close", "text": "Say there''s nothing to hide in food and it comes with a 30 day money back guarantee."}]', 'Comment bubble on screen, you and your dog on the couch', 'The full melt shown in one unbroken shot', '[{"brand": "Spot & Tango", "what": "Put a real comment on screen (does your dog actually take it?) with your dog in your lap, then answer by showing it: strip on the tongue, start to finish.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('061a1bdf19466e77', 'brand_vetripaws', '9265756226e91e3c', 'upload', 'amb/brand_vetripaws/inspo-snt-comment-reply.mp4', 'Spot & Tango (inspiration)', 'Put a real comment on screen (does your dog actually take it?) with your dog in your lap, then answer by showing it: strip on the tongue, start to finish.', '2efba8ff5a73e351', 1, 1, 9);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('ab2bfb7b6ba70384', 'brand_vetripaws', '320f10c21591266a', 0, 0, 10, 'live', 'Warning: don''t give this to your old dog', 'A fake warning is a pattern break, and the payoff is a happy older dog moving around.', 'Owner of an older dog who still has spark', 'Bone & Joint', 'Fake warning skit', '["Warning: your dog will start asking for this.", "Now he waits by the tin every morning, and then the leash.", "Nobody warned me about this part."]', '[{"label": "Open · 0 to 3s", "text": "Tin in hand. Text: WARNING."}, {"label": "Middle", "text": "Clips of your dog playing, running up to you, going up steps. Strip on the tongue at breakfast."}, {"label": "Close", "text": "Dog sitting proud next to the tin. Say you''re supporting their joints every day."}]', 'Text on screen: WARNING, don''t buy this', 'Dog zooming through the house', '[{"brand": "Wuffes", "what": "Joke warning up front, then clips of your older dog being bouncy: running to the door, jumping on the bed, playing in the yard. Show the strip in the morning routine.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('01cf6b4f9a3d2a72', 'brand_vetripaws', 'ab2bfb7b6ba70384', 'upload', 'amb/brand_vetripaws/inspo-wuf-warning-puppy.mp4', 'Wuffes (inspiration)', 'Joke warning up front, then clips of your older dog being bouncy: running to the door, jumping on the bed, playing in the yard. Show the strip in the morning routine.', '320f10c21591266a', 1, 1, 10);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('59fb2ddf28986dd9', 'brand_vetripaws', '502a835331b56cfd', 0, 0, 11, 'live', 'Two owners, one itchy dog', 'Two real people talking about their own dog feels honest and is easy to film at home.', 'A couple, older owners work great here', 'Skin & Coat', 'Two-person talk to camera', '["We tried everything for her itching.", "Him: shampoos. Me: creams. Her: still scratching.", "Here''s what we wish we''d known a year ago."]', '[{"label": "Open · 0 to 3s", "text": "Both of you with the dog between your legs."}, {"label": "Middle", "text": "Close ups of the scratching. The shelf of stuff you tried. Strip on the tongue."}, {"label": "Close", "text": "Unboxing the tin with the dog sniffing it. Both say why you''re sticking with it."}]', 'Couple standing side by side with the dog sitting between them', 'The pile of shampoos and creams that didn''t stop it', '[{"brand": "Dog is Human", "what": "Stand with your partner and your dog and talk about the scratching together, trading lines. Show the bottles and creams you tried, then the strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('32b02d9a31c90874', 'brand_vetripaws', '59fb2ddf28986dd9', 'upload', 'amb/brand_vetripaws/inspo-dih-couple-itchy.mp4', 'Dog is Human (inspiration)', 'Stand with your partner and your dog and talk about the scratching together, trading lines. Show the bottles and creams you tried, then the strip.', '502a835331b56cfd', 1, 1, 11);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('9d54c5647c892f2e', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 12, 'live', 'Kisses that smell like fish', 'The recoil is funny and true, and the strip is easier than brushing.', 'Owner whose dog loves face kisses', 'Fresh Breath', 'Kiss recoil, before and after', '["Tired of puppy kisses that smell like fish?", "I love him. I do not love his breath.", "Brushing his teeth every day? Be serious."]', '[{"label": "Open · 0 to 3s", "text": "Dog kiss, you recoil."}, {"label": "Middle", "text": "Toothbrush struggle on the couch. Then strip on the tongue, gone."}, {"label": "Close", "text": "Kiss again, you lean in. Say you''re supporting fresher breath with one strip a day."}]', 'Dog licking your face and you turning away', 'Wrestling a toothbrush into your dog''s mouth', '[{"brand": "PetLab Co.", "what": "Your dog goes in for a kiss and you pull back with a face. Show how you used to fight with a toothbrush, then the strip, then a kiss you don''t dodge.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('01a1acf04eeb81d6', 'brand_vetripaws', '9d54c5647c892f2e', 'upload', 'amb/brand_vetripaws/inspo-plc-fish-kisses.mp4', 'PetLab Co. (inspiration)', 'Your dog goes in for a kiss and you pull back with a face. Show how you used to fight with a toothbrush, then the strip, then a kiss you don''t dodge.', '2efba8ff5a73e351', 1, 1, 12);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('fafdd48610054c97', 'brand_vetripaws', '320f10c21591266a', 0, 0, 13, 'live', 'I wish I started sooner', 'Regret from a real owner is more convincing than any claim, and it pushes younger-dog owners too.', 'Owner of a very old dog, or someone with an old and a young dog', 'Bone & Joint', 'Talking head, holding the dog', '["One thing I wish I did way sooner with my old dog.", "He''s 14. Here''s my one regret.", "If your dog is 6 or older, don''t sleep on this."]', '[{"label": "Open · 0 to 3s", "text": "You with your dog in your arms, talking to camera."}, {"label": "Middle", "text": "Put the dog down, open the tin, read the label out loud (vet formulated, Bone & Joint), strip on the tongue."}, {"label": "Close", "text": "Say: don''t wait like I did."}]', 'You holding your senior dog, finger up: one thing I wish I did sooner', 'The strip melting on your old dog''s tongue', '[{"brand": "Wuffes", "what": "Hold your older dog and talk straight to camera about the one thing you wish you''d started earlier: daily joint support. Show the tin and a strip going on.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('25c34391d0479881', 'brand_vetripaws', 'fafdd48610054c97', 'upload', 'amb/brand_vetripaws/inspo-wuf-wish-sooner.mp4', 'Wuffes (inspiration)', 'Hold your older dog and talk straight to camera about the one thing you wish you''d started earlier: daily joint support. Show the tin and a strip going on.', '320f10c21591266a', 1, 1, 13);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('3ff95c1888f53fb2', 'brand_vetripaws', '502a835331b56cfd', 0, 0, 14, 'live', 'The scratching that never stops', 'Owners recognise the constant scratching instantly, and the calm ending is what they want.', 'Owner of a small or medium itchy dog', 'Skin & Coat', 'Problem montage, then routine', '["Scratch. Scratch. Scratch. All day.", "If your dog can''t stop scratching, keep watching.", "Creams work on the outside. I wanted something for the inside."]', '[{"label": "Open · 0 to 3s", "text": "Dog scratching, fast cuts."}, {"label": "Middle", "text": "Strip on the tongue, the dog licking lips."}, {"label": "Close", "text": "Dog relaxed on your lap, you smiling at camera."}]', 'Dog mid-scratch on the rug', 'Third scratch clip in a row, you sigh', '[{"brand": "Native Pet", "what": "Quick clips of your dog scratching on the rug, on the couch, in the yard. Then the strip as your daily step and a calm dog on your lap.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('9a0a7384cdb13a93', 'brand_vetripaws', '3ff95c1888f53fb2', 'upload', 'amb/brand_vetripaws/inspo-nat-cavalier-itch.mp4', 'Native Pet (inspiration)', 'Quick clips of your dog scratching on the rug, on the couch, in the yard. Then the strip as your daily step and a calm dog on your lap.', '502a835331b56cfd', 1, 1, 14);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('f803b0d5193f186f', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 15, 'live', 'I''d rather do his breath than ...', 'An odd claim in the first line makes people stay for the why, and the why is how easy the strip is.', 'Owners who gave up on the toothbrush', 'Fresh Breath', 'Odd claim hook, talking head outside', '["I''d rather do my dog''s breath than my husband''s. Hear me out.", "I''d rather freshen his breath than mine, and that''s saying something.", "You''re going to think this is weird, but dog breath is the easy part of my day."]', '[{"label": "Open · 0 to 3s", "text": "Talking head outside, tin in hand. Say the ''I''d rather'' line."}, {"label": "Middle", "text": "Cut to the strip on the dog''s tongue, then back to you: no brush, no fight, it''s gone in about 30 seconds and supports fresh breath."}, {"label": "Close", "text": "Pick up or hug the dog with the tin in frame. Say: and now I actually want the kisses."}]', 'You outside, straight to camera, holding the tin: I''d rather do my dog''s breath than my husband''s', 'Quick cut of the strip going on the tongue, no brush, no wrestling', '[{"brand": "Meow Mouth", "what": "Open with a funny ''I''d rather'' line straight to camera outside, then say why breath care stopped being a fight. End holding your dog with the tin.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('b49cf9f5c5a76108', 'brand_vetripaws', 'f803b0d5193f186f', 'upload', 'amb/brand_vetripaws/inspo-mm-id-rather.mp4', 'Meow Mouth (inspiration)', 'Open with a funny ''I''d rather'' line straight to camera outside, then say why breath care stopped being a fight. End holding your dog with the tin.', '2efba8ff5a73e351', 1, 1, 15);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('e01ecc58a8afecc5', 'brand_vetripaws', '320f10c21591266a', 0, 0, 16, 'live', 'A day with my dog', 'Day-in-the-life clips feel like a friend''s post, not an ad, and the strip fits naturally into the morning.', 'Active owner who walks or runs with their dog', 'Bone & Joint', 'Day in the life vlog', '["This is Koda. He''s 9 and he still wants to run every day.", "Come with us for a day.", "Here''s how I keep my old boy moving."]', '[{"label": "Open · 0 to 3s", "text": "Dog running toward you on grass, name on screen."}, {"label": "Middle", "text": "Kitchen in the morning, strip on the tongue, food bowl, leash."}, {"label": "Close", "text": "Fetch or a walk in the park. Thumbs up to camera."}]', 'Your dog running at the camera. Text: this is Koda (your dog''s name)', 'Morning routine: strip on the tongue before the walk', '[{"brand": "Native Pet", "what": "Introduce your dog by name, then film your day together: morning strip, the walk, the park. Talk over it like a vlog.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('5f3c4a13ab775ab5', 'brand_vetripaws', 'e01ecc58a8afecc5', 'upload', 'amb/brand_vetripaws/inspo-nat-day-with-koda.mp4', 'Native Pet (inspiration)', 'Introduce your dog by name, then film your day together: morning strip, the walk, the park. Talk over it like a vlog.', '320f10c21591266a', 1, 1, 16);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('2da37f3be2e38c72', 'brand_vetripaws', '502a835331b56cfd', 0, 0, 17, 'live', 'Bath day with my most dramatic client', 'Grooming drama is fun to watch, and the brush is the natural place to talk about coat and shedding.', 'Owners who bathe and brush at home', 'Skin & Coat', 'Groom with me, funny captions', '["My worst client is back. Send help.", "Bath day. He has already filed a complaint.", "Grooming my most dramatic client, again."]', '[{"label": "Open · 0 to 3s", "text": "Dog in the tub or sink looking betrayed. Caption: my worst client is back, send help."}, {"label": "Middle", "text": "Towel off, brushing on the floor. Captions: brush day, then the strip goes on, it supports skin and coat from the inside."}, {"label": "Close", "text": "Fluffy dog lying down, done. Caption: client satisfied, tip paid in kisses."}]', 'Wet, unimpressed dog in the tub staring at the camera, caption: my worst client is back, send help', 'Close up of the brush after the session, caption: less fur in here than last month', '[{"brand": "Rhykin Pet Co", "what": "Film bath and brush day at home like your dog is your hardest customer. Funny captions about the drama, then the brush, and the strip as the reward at the end.", "url": null}]');
