INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('d4f14501b0e77800', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 18, 'live', 'I let my dog pick', 'Owners doubt a dog will take a supplement. Watching the dog choose it from a lineup answers that better than any claim.', 'Owners of picky dogs, or homes with more than one dog', 'Fresh Breath', 'Lineup, let them pick', '["I put four things in front of my dog and let him pick.", "Cheese, biscuit, carrot, or a vitamin strip. Watch.", "Which one does she go for first? I genuinely didn''t know."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot from floor level: the lineup, dog coming in. Caption: which one does he pick?"}, {"label": "Middle", "text": "The sniff test along the row, then the pick. Name each item as they pass it."}, {"label": "Close", "text": "Strip on the tongue, gone in about 30 seconds. Say: so that''s the vitamins sorted."}]', 'Row of options on the floor (cheese, a biscuit, a carrot, a strip), dog walking in from the side', 'Dog skips the cheese and goes for the strip, slow motion is fine', '[{"brand": "Viva Raw", "what": "Line up a few things your dog loves on the floor with a VetriPaws strip in the row, then let them choose. Film from their level. If you have more than one dog, let each one pick.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('9c231ed126e1e3b3', 'brand_vetripaws', 'd4f14501b0e77800', 'upload', 'amb/brand_vetripaws/inspo-viva-let-them-pick.mp4', 'Viva Raw (inspiration)', 'Line up a few things your dog loves on the floor with a VetriPaws strip in the row, then let them choose. Film from their level. If you have more than one dog, let each one pick.', '2efba8ff5a73e351', 1, 1, 18);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('271c9de7ba6e6a85', 'brand_vetripaws', '320f10c21591266a', 0, 0, 19, 'live', 'The question everyone asks about my dog', 'Owners trust another owner answering a real question more than any pitch, and the walk footage makes the point without a word.', 'Owners of older or stiff dogs who get asked about their dog on walks', 'Bone & Joint', 'FAQ captions over walk footage', '["Why does my dog get a strip every morning? The question I get asked most.", "No, it''s not candy. Here''s what I give him before every walk.", "People at the park keep asking what I give her. So here it is."]', '[{"label": "Open · 0 to 3s", "text": "Walk shot from behind, phone low. Caption: why does my dog get a strip every single morning?"}, {"label": "Middle", "text": "Quick kitchen shot: tin open, strip on the tongue until it''s gone. Captions: it supports his joints, it''s vet formulated, he takes it like a snack."}, {"label": "Close", "text": "Back on the walk, dog trotting ahead. Caption: it''s just part of our morning now."}]', 'Dog walking away from camera on the trail, caption: why does my dog get a strip every single morning?', 'Cut to the kitchen: strip on the tongue, gone in about 30 seconds, then back out the door', '[{"brand": "Wagwear", "what": "Answer the one question people always ask about your older dog, in captions over your normal walk. Why does he get a strip every morning? Show it going on, then let the walk do the talking.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('f6c275f5a3523b1e', 'brand_vetripaws', '271c9de7ba6e6a85', 'upload', 'amb/brand_vetripaws/inspo-wag-alfie-shoes.mp4', 'Wagwear (inspiration)', 'Answer the one question people always ask about your older dog, in captions over your normal walk. Why does he get a strip every morning? Show it going on, then let the walk do the talking.', '320f10c21591266a', 1, 1, 19);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('c10b9a496c9a3554', 'brand_vetripaws', '502a835331b56cfd', 0, 0, 20, 'live', 'Shedding season non-negotiables', 'A fast list everyone with a shedding dog recognises, and the strip lands last as the one that works from the inside.', 'Owners of heavy shedders (goldens, huskies, labs, shepherds)', 'Skin & Coat', 'Non-negotiables list, quick cuts', '["Lint roller, vacuum, brush, and this. The non-negotiables.", "Shedding season with a golden. Here''s what I can''t live without.", "Things I own because my dog sheds, ranked."]', '[{"label": "Open · 0 to 3s", "text": "Hold up a fur covered lint roller. Say: shedding season non-negotiables."}, {"label": "Middle", "text": "One quick shot each: vacuum, brush on the dog, then the tin and a strip on the tongue."}, {"label": "Close", "text": "Tin and dog together. Say: the first three clean up the fur, this one supports the coat from the inside."}]', 'You holding up a lint roller covered in dog hair: shedding season non-negotiables', 'Last cut: tin opening and the strip going on the tongue, caption: the one that works from the inside', '[{"brand": "Touchland", "what": "Quick cuts naming your shedding season must haves, one item per shot: lint roller, vacuum, brush, and the VetriPaws tin last. Say each one out loud with the dog in the shot.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('a304d0193a1a3919', 'brand_vetripaws', 'c10b9a496c9a3554', 'upload', 'amb/brand_vetripaws/inspo-tl-non-negotiables.mp4', 'Touchland (inspiration)', 'Quick cuts naming your shedding season must haves, one item per shot: lint roller, vacuum, brush, and the VetriPaws tin last. Say each one out loud with the dog in the shot.', '502a835331b56cfd', 1, 1, 20);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('5b9b13c8a4a37579', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 21, 'live', 'The doorbell camera caught it', 'Doorbell clips feel caught, not made, so people believe them. A dog kiss you don''t dodge says more about breath than any claim.', 'Owners with a doorbell camera or a porch, couples, anyone who used to turn their face away from dog kisses', 'Fresh Breath', 'Doorbell camera skit', '["Doorbell camera caught me letting the dog kiss me. Again.", "My wife watched this on the doorbell camera and called me.", "Six months ago I''d have turned my face away. Watch."]', '[{"label": "Open · 0 to 3s", "text": "Doorbell camera or a phone propped low by the door: you walk up, door opens, dog runs out and goes for your face. Caption: what are you doing?"}, {"label": "Middle", "text": "The back and forth in captions (did you just let him lick you? his breath is fine now). Cut to the strip going on his tongue that morning."}, {"label": "Close", "text": "Back on the porch, dog still in your face, you laughing. Caption: one strip a day, and I take the kisses now."}]', 'Wide, low doorbell camera angle of the front porch, dog bursting out the door to meet you', 'Voice through the doorbell: did you just let him lick your face?', '[{"brand": "Bogey Bros Golf Co", "what": "Film it like your doorbell camera caught it: you come home, the dog meets you on the porch and goes straight for your face. Your partner''s voice comes through the doorbell asking what you''re doing. Captions for the back and forth.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('14decb965f4de4e2', 'brand_vetripaws', '5b9b13c8a4a37579', 'upload', 'amb/brand_vetripaws/inspo-bb-doorbell-kiss.mp4', 'Bogey Bros Golf Co (inspiration)', 'Film it like your doorbell camera caught it: you come home, the dog meets you on the porch and goes straight for your face. Your partner''s voice comes through the doorbell asking what you''re doing. Captions for the back and forth.', '2efba8ff5a73e351', 1, 1, 21);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('352aa34ecca43679', 'brand_vetripaws', '320f10c21591266a', 0, 0, 22, 'live', 'Tin in hand, then come on the walk', 'The tin and the dog share the first frame, so the viewer gets the product and the payoff in one second.', 'Senior dog owners who still walk every day', 'Bone & Joint', 'Walk with me voiceover, product up front', '["These are the strips my old girl gets every morning. Come on our walk.", "Holding the tin, but watch who''s behind it.", "She''s eleven. Come walk with us."]', '[{"label": "Open · 0 to 3s", "text": "Tin held up close, dog in the background. Say: these are the strips she gets every morning."}, {"label": "Middle", "text": "Flip to the walk, phone at dog height. Talk over it: one strip on the tongue, dissolves in about 30 seconds, supports her joints."}, {"label": "Close", "text": "Dog trotting ahead or looking back at you. Say: this is our favorite part of the day."}]', 'VetriPaws tin held close to the lens, older dog sniffing around right behind it', 'Dog trotting to catch up with you on the path, voice says: look at her go', '[{"brand": "Pawprint Lab", "what": "Start holding the tin up close with your dog behind it, then flip to the walk and talk over it like you''re telling a friend. Keep it loose and real, just you, the dog and the trail.", "url": null}]');
