INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('08e68a88986e0eab', 'brand_vetripaws', '502a835331b56cfd', 0, 0, 23, 'live', 'Beach day with my dog', 'Water, sand and sun show off a coat better than anything indoors. Owners see a glossy, happy dog and want that for theirs.', 'Owners near a beach, lake or river, water loving dogs, short and smooth coats look great', 'Skin & Coat', 'Beach day montage', '["Taking her to the beach and her coat is the main character.", "Salt water, sand, sun. Her coat still looks like this.", "Beach day with my dog, start to finish."]', '[{"label": "Open · 0 to 3s", "text": "Wide from the sand: dog running into the water. Caption: beach day."}, {"label": "Middle", "text": "Close ups: wet coat in the sun, the shake off in slow motion, sandy paws, strip on the tongue in the car park before you go."}, {"label": "Close", "text": "Dog drying in the sun on the sand, coat soft and shiny. Caption: one strip a day for skin and coat."}]', 'Wide shot of the dog running into the waves, then a close up of the wet coat shining in the sun', 'The full body shake off in slow motion', '[{"brand": "Pawezy", "what": "A beach or lake day in short clips: running in the water, the shake off, rolling in the sand, the coat drying in the sun. Short captions over each clip. Add the strip going on before you head out.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ea16766116f315e7', 'brand_vetripaws', '08e68a88986e0eab', 'upload', 'amb/brand_vetripaws/inspo-pwz-beach-day.mp4', 'Pawezy (inspiration)', 'A beach or lake day in short clips: running in the water, the shake off, rolling in the sand, the coat drying in the sun. Short captions over each clip. Add the strip going on before you head out.', '502a835331b56cfd', 1, 1, 23);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('b421a3613d71fc72', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 24, 'live', 'I asked dog owners at the park', 'Strangers at the park saying the thing every owner thinks lands harder than one person on camera. It shows bad dog breath is normal and easy to sort.', 'Creators who can film a friend or two at a park, any dog', 'Fresh Breath', 'Street interview at the dog park', '["Honest question: when did you last smell your dog''s breath?", "I asked dog owners at the park one thing about their dog.", "Would you let your dog kiss you right now? Be honest."]', '[{"label": "Open · 0 to 3s", "text": "Two people on the grass, mic in hand, dog sitting at their feet. Ask: would you let your dog kiss you right now?"}, {"label": "Middle", "text": "Their honest answer, a close shot of the dog, then hand them a strip and film it going on the dog''s tongue."}, {"label": "Close", "text": "Back to the two of them laughing with the dog. They say: no brushing, no fight? I''m in."}]', 'Two people standing on grass, one with a mic, a dog sitting between them', 'Strip on the dog''s tongue right there on the grass while the owner watches', '[{"brand": "Butternut Box", "what": "Street interview at your dog park: hold a mic (or just your phone) and ask owners one question about their dog''s breath. Keep it light, film it outside, let their dogs be in the shot. End by giving one of them a strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ddb4e155c737c1ba', 'brand_vetripaws', 'b421a3613d71fc72', 'upload', 'amb/brand_vetripaws/inspo-bnb-park-interview.mp4', 'Butternut Box (inspiration)', 'Street interview at your dog park: hold a mic (or just your phone) and ask owners one question about their dog''s breath. Keep it light, film it outside, let their dogs be in the shot. End by giving one of them a strip.', '2efba8ff5a73e351', 1, 1, 24);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('5d581791d6e10df1', 'brand_vetripaws', '2efba8ff5a73e351', 0, 0, 25, 'live', 'Car rides with my dog', 'A closed car is where dog breath hits you hardest. Every owner who takes their dog for rides knows the moment, so they get it in one second.', 'Owners who take their dog in the car, road trips, school runs, park trips', 'Fresh Breath', 'Car ride captions, filmed in the back seat', '["Every car ride, this face, right next to mine.", "Windows up, dog in the back. You know the smell.", "Car rides used to mean windows down. In October."]', '[{"label": "Open · 0 to 3s", "text": "Phone on the dash or held from the front seat: dog leaning between the seats, panting. Caption: windows up, dog in the back."}, {"label": "Middle", "text": "Parked before the ride, one strip on the tongue, gone in about 30 seconds. Captions over the dog settling into the seat."}, {"label": "Close", "text": "Dog happy in the back seat during the ride, leaning in for a kiss. Caption: road trips just got better."}]', 'Dog''s face pushed between the front seats, panting at the camera', 'Strip on the tongue in the parked car, dog sitting up in the back seat', '[{"brand": "WaggingRights", "what": "Film it all in the car: your dog in the back seat, head between the seats, panting right next to you. Captions over the ride, then the strip going on before you set off. Phone on the dash or filmed while parked.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('6d19e6fd3d99928f', 'brand_vetripaws', '5d581791d6e10df1', 'upload', 'amb/brand_vetripaws/inspo-wr-back-seat.mp4', 'WaggingRights (inspiration)', 'Film it all in the car: your dog in the back seat, head between the seats, panting right next to you. Captions over the ride, then the strip going on before you set off. Phone on the dash or filmed while parked.', '2efba8ff5a73e351', 1, 1, 25);
